const $ = (id) => document.getElementById(id);
const ce = (tag, cls, html) => {
  const el = document.createElement(tag);
  if (cls) el.className = cls;
  if (html != null) el.innerHTML = html;
  return el;
};

/**
 * 通用说明弹窗：替代 alert，保持界面风格一致。
 * actions: [{ text, primary, onClick }]，不传就只有一个「关闭」。
 */
/* ---------- MCP 工具调用：应用内确认页 ---------- */
const mcpConfirmState = { active: false, queue: [] };

function enqueueMcpConfirm(payload) {
  if (!payload || !payload.id) return;
  mcpConfirmState.queue.push(payload);
  pumpMcpConfirm();
}

function pumpMcpConfirm() {
  if (mcpConfirmState.active) return;
  const payload = mcpConfirmState.queue.shift();
  if (!payload) return;
  mcpConfirmState.active = true;
  showMcpConfirm(payload);
}

function showMcpConfirm(payload) {
  const destructive = payload.destructive === true;
  const mask = ce('div', 'modal-mask');
  mask.innerHTML = `
    <div class="modal" style="width:min(620px,94vw);max-height:92vh;display:flex;flex-direction:column">
      <div class="modal-title">MCP 工具调用确认</div>
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:2px 0 12px">
        <span style="font-size:12px;padding:3px 8px;border-radius:999px;background:${destructive ? 'rgba(255,92,138,.14)' : 'rgba(80,220,160,.14)'};color:${destructive ? '#ff8a9e' : '#65e0a6'};border:1px solid ${destructive ? 'rgba(255,92,138,.35)' : 'rgba(80,220,160,.3)'}">
          ${destructive ? '可能写入 / 执行 / 联网' : '只读工具'}
        </span>
        <span style="font-size:12.5px;color:var(--text-dim)">${escapeHtml(payload.serverName || payload.serverId || 'MCP server')}</span>
      </div>
      <div style="font-size:13px;line-height:1.75;margin-bottom:10px">
        允许星云 AI 调用 <b style="color:var(--text)">${escapeHtml(payload.toolName || '')}</b>？
      </div>
      <div style="flex:1;min-height:0;overflow:auto;font-size:12.5px;line-height:1.75">
        <div style="color:var(--text-dim)">${escapeHtml(payload.description || '该工具没有提供说明。')}</div>
        <div style="margin-top:10px;color:var(--text-dim)">${payload.isHttp ? '连接地址' : '启动命令'}</div>
        <div style="margin-top:3px;padding:8px 10px;border-radius:8px;background:rgba(255,255,255,.05);word-break:break-all;font-family:ui-monospace,Consolas,monospace">${escapeHtml(payload.command || '')}</div>
        <div style="margin-top:10px;color:var(--text-dim)">参数</div>
        <pre style="margin:4px 0 0;padding:9px 10px;border-radius:8px;background:rgba(255,255,255,.05);white-space:pre-wrap;word-break:break-word;font-size:12px;max-height:220px;overflow:auto">${escapeHtml(payload.argsText || '{}')}</pre>
      </div>
      <div style="margin-top:12px;font-size:12px;color:${destructive ? '#ff8a9e' : 'var(--text-dim)'}">
        ${destructive ? '这个工具可能修改文件、执行命令或联网，每次调用都需要确认。' : '该工具声明为只读；勾选后本会话内不再询问。'}
      </div>
      <label style="display:${destructive ? 'none' : 'flex'};align-items:center;gap:8px;margin-top:9px;font-size:12.5px;color:var(--text-dim);cursor:pointer">
        <input type="checkbox" id="mcp-confirm-remember"> 本会话不再询问 ${escapeHtml(payload.toolName || '')}
      </label>
      <div class="modal-actions">
        <span id="mcp-confirm-count" style="margin-right:auto;font-size:12px;color:var(--text-dim)">120 秒后自动拒绝</span>
        <button class="btn ghost" id="mcp-confirm-deny" type="button">拒绝</button>
        <button class="btn primary" id="mcp-confirm-allow" type="button">允许一次</button>
      </div>
    </div>`;
  document.body.appendChild(mask);

  let closed = false;
  let left = 120;
  const countEl = mask.querySelector('#mcp-confirm-count');
  const timer = setInterval(() => {
    left -= 1;
    if (countEl) countEl.textContent = `${Math.max(0, left)} 秒后自动拒绝`;
  }, 1000);
  const finish = (allow, remember) => {
    if (closed) return;
    closed = true;
    clearInterval(timer);
    document.removeEventListener('keydown', onKey, true);
    try { api.mcpConfirmReply(payload.id, { ok: allow, remember: allow && remember }); } catch { /* 主进程超时会兜底拒绝 */ }
    mask.remove();
    mcpConfirmState.active = false;
    document.body.style.overflow = '';
    pumpMcpConfirm();
  };
  const onKey = (ev) => {
    if (ev.key === 'Escape') {
      ev.preventDefault();
      ev.stopPropagation();
      finish(false, false);
    }
  };
  document.addEventListener('keydown', onKey, true);
  document.body.style.overflow = 'hidden';
  mask.querySelector('#mcp-confirm-allow').onclick = () => finish(true, !!(mask.querySelector('#mcp-confirm-remember') || {}).checked);
  mask.querySelector('#mcp-confirm-deny').onclick = () => finish(false, false);
  mask.onclick = (ev) => { if (ev.target === mask) finish(false, false); };
  setTimeout(() => mask.querySelector('#mcp-confirm-deny').focus(), 50);
}

function infoModal(title, bodyHtml, actions) {
  const mask = ce('div', 'modal-mask');
  mask.innerHTML = `
    <div class="modal" style="width:460px">
      <div class="modal-title">${title}</div>
      <div style="font-size:13px;line-height:1.8;margin:12px 0;max-height:56vh;overflow-y:auto">${bodyHtml}</div>
      <div class="modal-actions"></div>
    </div>
  `;
  const acts = mask.querySelector('.modal-actions');
  const close = () => mask.remove();
  (actions && actions.length ? actions : [{ text: '关闭' }]).forEach((a) => {
    const b = ce('button', 'btn' + (a.primary ? ' primary' : ''), a.text);
    b.onclick = () => {
      close();
      if (a.onClick) a.onClick();
    };
    acts.appendChild(b);
  });
  mask.onclick = (e) => { if (e.target === mask) close(); };
  document.body.appendChild(mask);
  return mask;
}

// 全局 AI 按钮点击函数（HTML onclick 直接调用）
function openAI() {
  try {
    const cfg = readAIChatConfig();
    // 没有 Key（首次使用，或旧版内置的死 Key 已被清理）→ 先去设置页填 Key
    if (!cfg.apiKey) {
      openAISettings();
      return;
    }
    openAIChat();
  } catch (e) {
    alert('AI 功能错误：' + e.message);
  }
}

// i18n 快捷翻译函数（app.js 文案国际化统一入口）
const t = (key, vars) => (window.i18n ? window.i18n.t(key, vars) : key);

/** 统一去掉 Electron ipcRenderer.invoke 包装的
 *  「Error invoking remote method 'ai:chat': Error: ...」前缀，只留可读原因 */
function aiErrorText(e) {
  return String((e && e.message) || e || '未知错误').replace(/^.*?Error:\s*/, '');
}

/** 去掉 ipcRenderer.invoke 包装前缀，保留主进程给出的可读错误（联机工具等） */
function ipcErrorText(e) {
  return String((e && e.message) || e || '未知错误')
    .replace(/^Error invoking remote method '[^']+':\s*/, '')
    .replace(/^Error:\s*/, '');
}

/**
 * 增强下拉：把原生 select 包成「点开弹列表」的自定义控件。
 * 原生 select 弹窗在 WebView2 下滚动条不可控、滚轮常划不动，这里换成
 * 自定义弹出列表（可见滚动条 + 滚轮滚动 + 点击选中）。
 * 底层 select 保留（绝对定位透明盖层），onchange 事件、value 读写全部照旧。
 */
function enhanceSelect(sel) {
  if (!sel || sel.dataset.esel) return sel;
  sel.dataset.esel = '1';
  // 全局注册：切页面 / 开新弹窗时强制关闭所有打开的下拉，避免“切到别的页它还在显示”
  window.__eselReg = window.__eselReg || [];
  window.closeAllEsel = window.closeAllEsel || function () {
    (window.__eselReg || []).forEach((r) => { try { r.close(); } catch (e) {} });
  };
  const wrap = ce('div', 'esel');
  sel.parentNode.insertBefore(wrap, sel);
  wrap.appendChild(sel);

  const cur = ce('div', 'esel-cur');
  wrap.appendChild(cur);
  const list = ce('div', 'esel-list');
  wrap.appendChild(list);

  const sync = () => {
    const o = sel.options[sel.selectedIndex];
    cur.textContent = o ? o.textContent : '';
    cur.title = o ? o.textContent : '';
  };

  // 滚动页面 / 弹窗内容时自动收起下拉（像正常下拉菜单一样，别挡着看内容）；
  // 但下拉列表自己滚动选项时不能误关，所以排除 esel-list 自身的滚动
  const onScrollClose = (e) => {
    const t = e.target;
    if (t === list || (t && t.classList && t.classList.contains('esel-list'))) return;
    close();
  };
  const openScrollLock = () => document.addEventListener('scroll', onScrollClose, { capture: true });
  const offScrollLock = () => document.removeEventListener('scroll', onScrollClose, { capture: true });

  const close = () => {
    list.classList.remove('open');
    offScrollLock();
    // 弹层放回原位（.esel 内）。下次 open 再挂到 body：若停留在带
    // backdrop-filter 的胶囊里，其存在本身不影响（display:none），
    // 但保持结构干净，避免影响兄弟布局。
    if (list.parentNode && list.parentNode !== wrap) wrap.appendChild(list);
  };
  window.__eselReg.push({ list, close });

  const open = () => {
    // 关键：列表先挂到 body 再 fixed 定位。.sel-field / .input 等控件带
    // backdrop-filter（磨砂胶囊），Chromium 会把带 filter 的后代 fixed 元素
    // 的包含块劫持到该祖先上——视口坐标叠祖先偏移，弹窗就错位（本 bug 根因）。
    // 挂到 body 后 fixed 只认视口，位置永远正确。
    document.body.appendChild(list);
    list.innerHTML = '';
    // fixed 视口定位：跳过 .hero overflow / .page 滚动容器的裁剪
    const r = wrap.getBoundingClientRect();
    list.style.position = 'fixed';
    list.style.left = r.left + 'px';
    list.style.width = Math.max(r.width, 140) + 'px';
    list.style.top = (r.bottom + 6) + 'px';
    Array.from(sel.options).forEach((o, i) => {
      const it = ce('div', 'esel-opt' + (o.selected ? ' on' : ''));
      it.textContent = o.textContent;
      it.title = o.title || '';
      it.onclick = () => {
        sel.selectedIndex = i;
        sync();
        close();
        sel.dispatchEvent(new Event('change'));
      };
      list.appendChild(it);
    });
    list.classList.add('open');
    openScrollLock();
    // 用选项数估算列表高度（避开 reflow 时机导致 offsetHeight 读到 0 的问题）；
    // 下方空间不够就向上弹（视口内永远可见，>= 容差处理贴底）
    const estH = Math.min(280, sel.options.length * 38 + 8);
    if (r.bottom + 6 + estH >= window.innerHeight && r.top - 6 - estH > 0) {
      list.style.top = (r.top - 6 - estH) + 'px';
    }
  };

  cur.onclick = (e) => {
    e.stopPropagation();
    if (list.classList.contains('open')) close();
    else open();
  };
  document.addEventListener('click', (e) => {
    if (!wrap.contains(e.target)) close();
  }, true);
  // 列表滚轮滚动天然生效（overflow-y:auto）；同步外部代码改 value 的情况
  const mo = new MutationObserver(() => sync());
  mo.observe(sel, { attributes: true, attributeFilter: ['disabled'], childList: true });
  sync();
  sel.__eselSync = sync;
  return sel;
}

/* ---------- MC 版本号比较（下拉/列表排序用） ----------
 * 字符串 sort() 会把 "1.9" 排在 "1.20.4" 前面、快照 "24w14a" 排在正式版前面，
 * 版本选择列表因此乱序。这里分段解析 + 类型分级，得到真正的“新 → 旧”降序。
 */
function parseMcVer(s) {
  s = String(s || '').trim();
  // 快照：24w14a / 24w14b
  let m = s.match(/^(\d{2})w(\d{1,2})([ab])?$/i);
  if (m) return { type: 1, nums: [+m[1], +m[2], m[3] ? (m[3].toLowerCase() === 'a' ? 0 : 1) : 0] };
  // 正式 / 预发布：1.20.4、1.20.4-pre2、1.20.4-rc1
  m = s.match(/^(\d+)\.(\d+)(?:\.(\d+))?(?:-(pre|rc)(\d+))?$/);
  if (m) return { type: 2, nums: [+m[1], +m[2], m[3] ? +m[3] : 0, m[4] ? (m[4] === 'pre' ? 0 : 1) : 2, m[5] ? +m[5] : 0] };
  // 远古：a1.0.0 / b1.7.3 / c0.0.1
  m = s.match(/^([abc])?(\d+)\.(\d+)(?:\.(\d+))?$/i);
  if (m) return { type: 0, nums: [m[1] ? (m[1].toLowerCase() === 'c' ? 0 : m[1].toLowerCase() === 'b' ? 1 : 2) : 3, +m[2], +m[3], m[4] ? +m[4] : 0] };
  return { type: -1, raw: s };
}
function mcVersionCmp(a, b) {
  const pa = parseMcVer(a), pb = parseMcVer(b);
  if (pa.type !== pb.type) return pb.type - pa.type; // 正式(2) > 快照(1) > 远古(0) > 未知(-1)
  if (pa.type === -1) return String(b).localeCompare(String(a)); // 未知回退字典序
  const na = pa.nums, nb = pb.nums;
  for (let i = 0; i < Math.max(na.length, nb.length); i++) {
    const x = i < na.length ? na[i] : 0, y = i < nb.length ? nb[i] : 0;
    if (x !== y) return y - x; // 降序：新在前
  }
  return 0;
}
/* ---------- 游玩报表：按天聚合 ---------- */

function playDayKey(ts = Date.now()) {
  const d = new Date(ts);
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

/** 保存按天记录，只保留最近 400 天，避免配置文件无限膨胀 */
function savePlayDaily(pd) {
  const keys = Object.keys(pd).sort();
  if (keys.length > 400) keys.slice(0, keys.length - 400).forEach((k) => { delete pd[k]; });
  state.config.playDaily = pd;
  api.configSet('playDaily', pd).catch(() => {});
}

const sortMcVersions = (arr) => [...new Set(arr)].sort(mcVersionCmp);

/**
 * 主版本前缀兼容评分（星云 mcVersionScore 移植）：判断候选 MC 版本与实例版本是否兼容。
 * 1.21.4 ↔ 1.21.x 互认（主版本前缀相同），精确相等最优，跨主版本不兼容。
 * 用于模组 / 依赖版本选择：同加载器下按兼容分排序，优先选与实例兼容的最新版，
 * 避免精确匹配失败时落到任意版本（装错 MC 版本）。
 */
function mcVersionScore(instMc, candMc) {
  if (!instMc || !candMc) return 0;
  if (instMc === candMc) return 100;
  const mainOf = (v) => String(v).split('.').slice(0, 2).join('.');
  return mainOf(instMc) === mainOf(candMc) ? 50 : 0;
}
/** 一个模组版本与实例版本的兼容分：取其声明的所有 MC 版本里的最高分 */
function bestMcVersionScore(v, instMc) {
  const gvs = (v.gameVersions || []).filter(Boolean);
  if (!gvs.length) return 0;
  return Math.max(...gvs.map((g) => mcVersionScore(instMc, g)));
}
/** 一个 CurseForge 文件与实例版本的兼容分（CF 文件同样带 gameVersions 数组） */
function bestFileScore(f, instMc) {
  const gvs = (f.gameVersions || []).filter(Boolean);
  if (!gvs.length) return 0;
  return Math.max(...gvs.map((g) => mcVersionScore(instMc, g)));
}

const state = {
  config: null,
  manifest: null,
  installed: [],
  currentPage: 'home',
  account: null,
  selectedInstance: null,
  busy: false,
  // 正在运行的实例 id 集合（多开支持，事件驱动维护）
  runningInst: new Set(),
};

const ACCENTS = [
  { id: 'axolotl', color: '#0a84ff' },
  { id: 'emerald', color: '#27bd5eff' },
  { id: 'cyan', color: '#22d3ee' },
  { id: 'violet', color: '#a78bfa' },
  { id: 'rose', color: '#fb7185' },
  { id: 'amber', color: '#fbbf24' },
  { id: 'sky', color: '#46c5fcff' },
];

/* ========== 初始化 ========== */

/**
 * 功能扩展脚本（feat_*.js）只负责设置页/联机页/皮肤页等扩展能力，
 * 首屏（首页 + 顶栏 + 侧栏）不依赖它们。等首帧画完后再按原顺序异步加载，
 * 避免十几个脚本的解析/执行挤进「窗口可交互」这段关键路径。
 */
function loadFeatureScripts() {
  const files = [
    'feat-hooks.js', 'feat_crash.js', 'feat_perf.js', 'feat_search.js', 'feat_share.js',
    'feat_theme.js', 'feat_disclaimer.js', 'feat_onboard.js', 'feat_skin.js', 'feat_update.js', 'feat_server.js',
    'feat_backup.js', 'feat_tools.js',
  ];
  let i = 0;
  const next = () => {
    const f = files[i++];
    if (!f) return;
    const s = document.createElement('script');
    s.src = f;
    s.onload = next;
    s.onerror = next; // 单个扩展失败不影响其余功能
    document.body.appendChild(s);
  };
  // 先让出这一帧把首屏画出来，再开始解析扩展脚本；
  // 用 setTimeout 而不是 rAF：窗口被遮挡时 rAF 会被浏览器暂停，扩展就永远不加载了
  setTimeout(next, 50);
}

async function init() {
  state.config = await api.configGetAll();
  applyNotifyOffset(state.config.notifyOffsetY);
  applyTheme();
  bindWindowControls();
  bindNav();
  bindTopbar();
  bindGlobalEvents();
  bindGlassAuto();
  bindSystemTheme();
  bindShortcuts();

  // 下载并发自动降级：高并发把失败率推高时主进程会自行降速，这里提示一次
  if (api.onDownloadConcurrency) {
    api.onDownloadConcurrency((p) => {
      state.dlConcurrency = p;
      if (!p.silent) {
        toast(`下载失败率升高，实际并发已自动降到 ${p.actual}（设置 ${p.configured}）`, true);
      }
      if ($('set-dl-threads-hint')) paintDlThreadsHint(p.configured, p.reduced ? p.actual : null);
      const tip = $('dl-concurrency-tip');
      if (tip && p.reduced) {
        tip.hidden = false;
        tip.textContent = `并发过高导致失败率升高，实际并发已自动降到 ${p.actual}（设置 ${p.configured}）。可到设置里调低并发后重试。`;
      }
    });
  }

  // 首屏只依赖本地配置：实例选择 / 账号都在这里同步确定，然后立刻渲染首页。
  // 版本清单是网络请求，以前 await 它，网络一慢启动后空白近 10 秒 —— 改为后台加载。
  const instances0 = state.config.instances || {};
  const selId = state.config.selectedInstance in instances0
    ? state.config.selectedInstance
    : firstInstanceId(instances0);
  state.selectedInstance = selId;
  state.account = state.config.account;
  state.accounts = state.config.accounts || [];
  // 顶栏用户区读的是 state.account，而 bindTopbar() 跑在上面那两行之前 ——
  // 那时 state.account 还是空的，只能画成「未登录」。所以这里必须再刷一次，
  // 否则重启启动器后顶栏永远是「未登录 / 👤」，跟账号页显示的登录态对不上。
  updateTopUser();

  renderPage('home');

  // 功能扩展脚本不参与首屏：等窗口画出来后再按原顺序异步加载，
  // 首屏可交互时间因此不再包含这十几个文件的解析/执行。
  loadFeatureScripts();

  // 版本清单 / 已装版本后台补齐：
  // 不主动重渲染页面（会打断玩家正在进行的操作），首页版本下拉有自己的局部刷新，
  // 版本页等在渲染时若发现 manifest 缺失会自取。
  api.versionsManifest(true).then(async (m) => {
    state.manifest = m;
    state.installed = await api.versionsInstalled();
  }).catch((e) => toast(`版本清单加载失败：${e.message}`, true));

  // 侧栏底部的版本号写死在 HTML 里，打包换版本就会对不上，改成读真实版本；点它跳更新设置
  api.updaterVersion().then((uv) => {
    state.updateInfo = uv;
    const foot = $('foot-status');
    if (foot) {
      foot.title = `星云启动器 Nebula Launcher v${uv.version}${uv.portable ? '（免安装版）' : ''} · 点这里检查更新`;
      foot.onclick = openUpdateSettings;
      const ver = $('foot-ver');
      if (ver) ver.textContent = `v${uv.version} · 运行正常`;
    }
    // 首页冷启动时先渲染，真实 app 版本回来后再把更新日志与页脚版本补成实际版本
    const logVersion = $('changelog-version');
    if (logVersion) logVersion.textContent = `更新日志 v${uv.version}`;
    const homeFoot = $('home-foot-ver');
    if (homeFoot) homeFoot.textContent = `v${uv.version}`;
    const logBody = $('changelog-content');
    if (logBody && APP_CHANGELOG.some((x) => x.version === uv.version)) {
      logBody.innerHTML = changelogBodyHtml(uv.version);
    }
  }).catch(() => {});

  // 下载进度只有这一个监听口，DOM 不在（没停在设置页更新区）就什么都不做
  api.onUpdateProgress((p) => {
    const fill = $('up-fill');
    if (!fill) return;
    const track = $('up-progress');
    if (track) track.hidden = false;
    fill.style.width = `${p.percent || 0}%`;
    const mb = (n) => (n >= 1048576 ? `${(n / 1048576).toFixed(1)} MB` : `${Math.round(n / 1024)} KB`);
    const st = $('up-status');
    if (st) {
      st.textContent = `下载中 ${p.percent}% · ${mb(p.received)}${p.total ? ` / ${mb(p.total)}` : ''}`
        + (p.speed ? ` · ${(p.speed / 1048576).toFixed(1)} MB/s` : '');
    }
  });

  // 后台静默查更新，不挡界面
  autoCheckUpdate();
}

/** 从主进程刷新账号列表 */
async function refreshAccounts() {
  state.config = await api.configGetAll();
  state.accounts = state.config.accounts || [];
  state.account = state.config.account;
  updateTopUser();
}

/** 取当前配置实际生效的通透度：材质档优先于旧配置里残留的滑杆值。
 *  1.0.49 的「透明」档 g=100，升级后档位改成 74；旧配置里还存着 100，
 *  如果直接按 100 渲染，会出现“按钮亮着透明、滑杆却是 100%”的错位。 */
function glassLevelOf(ui) {
  const mat = GlassMotion.materialOf((ui || {}).glassMaterial);
  // custom 档的 g 是 null，不能直接 Number(null) —— 那会变成 0，
  // 把滑杆值整个吃掉，表现就是“能拖但界面完全不动”。
  const preset = mat && mat.g != null ? Number(mat.g) : NaN;
  if (Number.isFinite(preset)) return preset;
  const n = Number((ui || {}).glassLevel);
  if (Number.isFinite(n)) return Math.max(0, Math.min(100, Math.round(n)));
  return 55;
}

/** 把「通透度 0–100」写进 CSS 令牌：数值只负责“透多少”，
 *  真正的玻璃底、模糊、颗粒由材质档决定，再叠加滑杆连续微调。 */
function applyGlass() {
  const ui = state.config.ui || {};
  const mat = GlassMotion.materialOf(ui.glassMaterial);
  let g = glassLevelOf(ui);
  // 「自动」开启且窗口失焦时收一点，省电、不抢眼
  if (ui.glassAuto !== false && document.body.dataset.focus === '0') g = Math.max(0, g - 18);
  document.body.style.setProperty('--g', String(g / 100));
  document.body.style.setProperty('--glass-blur-k', String(mat.blurK));
  document.body.style.setProperty('--glass-blur-base', `${mat.blurBase == null ? 14 : mat.blurBase}px`);
  document.body.style.setProperty('--panel-floor', String(mat.panelFloor == null ? 0.14 : mat.panelFloor));
  document.body.setAttribute('data-material', mat.id);
  document.body.setAttribute('data-transparent', g >= 70 ? '1' : '0');
}

/** 把一个十六进制色转成 RGB，供强调色的半透明变体使用；不合法返回 null
 *  注意：下面实验室里的 hexToRgb 是老工具用的（永远返回数组），这里必须换个名字，
 *  否则两个同名函数会互相覆盖，非色号字符串也会被当成黑色强调色。 */
function accentHexRgb(hex) {
  const s = String(hex || '').trim().replace(/^#/, '');
  if (!/^([0-9a-f]{3}|[0-9a-f]{6})$/i.test(s)) return null;
  const full = s.length === 3 ? s.split('').map((c) => c + c).join('') : s;
  return [parseInt(full.slice(0, 2), 16), parseInt(full.slice(2, 4), 16), parseInt(full.slice(4, 6), 16)];
}

/** 自定义强调色：主色、加深一档的渐变副色、两层半透明光晕 */
function applyCustomAccent(hex) {
  const rgb = accentHexRgb(hex);
  if (!rgb) return false;
  const [r, g, b] = rgb;
  const dark = rgb.map((v) => Math.max(0, Math.round(v * 0.78)));
  const mix = (v, t) => v.map((c, i) => Math.round(c + (t - c) * 0.5));
  const toHex = (c) => '#' + c.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
  const second = (r + g + b) / 3 > 150 ? toHex(dark) : toHex(mix(rgb, 255));
  document.body.setAttribute('data-accent', 'custom');
  // 强调色主题（霓虹/薄荷/樱花）在 theme-apple.css 里带 !important，
  // 这里只能用内联 + important 才压得住，否则自定义色号会被主题色覆盖
  document.body.style.setProperty('--accent', '#' + rgb.map((v) => v.toString(16).padStart(2, '0')).join(''), 'important');
  document.body.style.setProperty('--accent-2', second, 'important');
  document.body.style.setProperty('--accent-glow', `rgba(${r}, ${g}, ${b}, 0.35)`, 'important');
  document.body.style.setProperty('--accent-soft', `rgba(${r}, ${g}, ${b}, 0.14)`, 'important');
  return true;
}

function clearCustomAccent() {
  if (document.body.getAttribute('data-accent') === 'custom') document.body.removeAttribute('data-accent');
  ['--accent', '--accent-2', '--accent-glow', '--accent-soft'].forEach((k) => document.body.style.removeProperty(k));
}

function applyTheme() {
  const accent = String(state.config.accent || 'axolotl');
  if (accentHexRgb(accent)) {
    applyCustomAccent(accent);
  } else {
    clearCustomAccent();
    document.body.setAttribute('data-accent', accent);
  }
  document.body.setAttribute('data-mode', resolveMode());
  const ui = Object.assign(
    { glassLevel: 55, glassAuto: true, density: 'normal', aura: 'std', fontSize: 'normal', contrast: 'normal', renderer: 'desktop' },
    state.config.ui || {},
  );
  document.body.setAttribute('data-density', ui.density);
  document.body.setAttribute('data-aura', ui.aura);
  document.body.setAttribute('data-fontsize', ui.fontSize || 'normal');
  document.body.setAttribute('data-contrast', ui.contrast || 'normal');
  document.body.setAttribute('data-renderer', ui.renderer === 'mobile' ? 'mobile' : 'desktop');
  syncBrandTitle(state.currentPage || 'home');
  // 字号缩放走页面缩放（主进程 setZoomFactor）：视口会跟着重排，
  // 不会像 body{zoom} 那样把 100vh 撑出屏幕，文字也不会被位图拉伸发虚
  const uiZoom = ui.fontSize === 'large' ? 1.06 : ui.fontSize === 'xlarge' ? 1.12 : 1;
  if (api.setUiZoom) api.setUiZoom(uiZoom).catch(() => {});
  applyGlass();
  applyWallpaper();
}

/* ---------- 明暗模式：深色 / 浅色 / OLED / 跟随系统 ---------- */

const THEME_OPTS = [
  { id: 'dark', label: '深色' },
  { id: 'light', label: '浅色' },
  { id: 'oled', label: 'OLED' },
  { id: 'system', label: '跟随系统' },
];

/** 把「跟随系统」解析成实际生效的 dark / light */
function resolveMode() {
  const t = state.config.theme || 'dark';
  if (t === 'system') {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  }
  return t;
}

function bindThemeOpts() {
  const box = $('ui-theme');
  if (!box) return;
  const cur = state.config.theme || 'dark';
  THEME_OPTS.forEach((o) => {
    const b = ce('button', 'ui-opt' + (o.id === cur ? ' on' : ''));
    b.type = 'button';
    b.textContent = o.label;
    b.onclick = () => {
      // 只清官方深浅色按钮的选中态；隐藏配色按钮（霓虹/薄荷/樱花）保持各自高亮，
      // 因为它们和深浅色是两套互不覆盖的设置（切换深/浅不该把配色取消掉）
      box.querySelectorAll('.ui-opt:not(.fx-secret-btn)').forEach((x) => x.classList.remove('on'));
      b.classList.add('on');
      state.config.theme = o.id;
      applyTheme();
      api.configUpdate({ theme: o.id });
    };
    box.appendChild(b);
  });
}

/** 选了「跟随系统」时，系统切换明暗要实时跟上 */
function bindSystemTheme() {
  const mq = window.matchMedia('(prefers-color-scheme: dark)');
  const onChange = () => {
    if ((state.config.theme || 'dark') === 'system') applyTheme();
  };
  if (mq.addEventListener) mq.addEventListener('change', onChange);
  else if (mq.addListener) mq.addListener(onChange);
}

/** 液态玻璃「自动」：窗口失焦时自动收一档 */
function bindGlassAuto() {
  const sync = (focused) => {
    document.body.setAttribute('data-focus', focused ? '1' : '0');
    applyGlass();
  };
  sync(document.hasFocus());
  window.addEventListener('focus', () => sync(true));
  window.addEventListener('blur', () => sync(false));
}

